# Entry-point script for Wi-Fi analytical workflow in R.
# The script reads processed outputs generated by Hadoop/Hive and creates charts.

project_root <- getwd()
if (!dir.exists(file.path(project_root, "r"))) {
  stop("Run this script from the project root directory, e.g. Rscript r/analysis.R")
}

source(file.path(project_root, "r", "visualizations.R"))

message("Running Wi-Fi analytics in R...")
run_wifi_visual_analysis()
